/* ============================================================ */
/* ENGINE                                                         */
/* ============================================================ */

// Placeholder until the real Echo Coins economy (from echovault-progression
// planning) is built into script1.js — keeps a running localStorage total
// so Riddle Den is fully testable now. Safe to delete once the real
// creditEchoCoins() exists elsewhere; this only defines it if missing.
if (typeof creditEchoCoins !== "function") {
  window.creditEchoCoins = function (amount) {
    const current = parseInt(localStorage.getItem("echoCoins") || "0", 10);
    localStorage.setItem("echoCoins", current + amount);
  };
}

function normalizeAnswer(str) {
  return str.toLowerCase().trim().replace(/[^\w\s]/g, "");
}

function checkAnswer(riddle, input) {
  const normalizedInput = normalizeAnswer(input);
  return riddle.answers.some(a => normalizeAnswer(a) === normalizedInput);
}

function getCoinReward(riddle, hintsUsed, gaveUp) {
  if (gaveUp) return Math.round(riddle.coinReward * 0.1);
  if (hintsUsed === 0) return riddle.coinReward;
  if (hintsUsed === 1) return Math.round(riddle.coinReward * 0.6);
  return Math.round(riddle.coinReward * 0.3); // 2 hints used
}

// riddleProgress stored in the Attic's own IndexedDB, keyed by riddle id
// { solved: bool, attempts: n, hintsUsed: n, gaveUp: bool, coinsEarned: n }

function submitRiddleAnswer(riddle, input, progress) {
  if (progress.solved) return { alreadySolved: true };

  progress.attempts++;
  const config = RIDDLE_CATEGORIES[riddle.category];
  const correct = checkAnswer(riddle, input);

  if (correct) {
    progress.solved = true;
    progress.coinsEarned = getCoinReward(riddle, progress.hintsUsed, false);
    creditEchoCoins(progress.coinsEarned); // hooks into the progression system
    return { correct: true, coinsEarned: progress.coinsEarned, explanation: riddle.explanation || null };
  }

  const hintIndexToShow = config.triesBeforeHint.filter(t => progress.attempts >= t).length - 1;
  const newHintAvailable = hintIndexToShow >= progress.hintsUsed;
  const showReveal = progress.attempts >= config.triesBeforeReveal;

  return { correct: false, newHintAvailable, showReveal, attempts: progress.attempts };
}

function giveUpOnRiddle(riddle, progress) {
  progress.solved = true;
  progress.gaveUp = true;
  progress.coinsEarned = getCoinReward(riddle, progress.hintsUsed, true);
  creditEchoCoins(progress.coinsEarned);
  return { answer: riddle.answers[0], explanation: riddle.explanation || null, coinsEarned: progress.coinsEarned };
}
